package it.frociart.app;
import java.util.*;import static it.frociart.app.FlowModel.*;
public final class CycleViewTests {
 static int checks;static void check(boolean yes,String why){if(!yes)throw new AssertionError(why);checks++;}
 static void verify(FlowCycleView model,Document original,String baseline){FlowCycleView.Projection p=model.build();check(FlowCodec.encode(original).equals(baseline),"Projection never edits original");Set<String> ids=new HashSet<>();for(Node n:p.graph.nodes)check(ids.add(n.id),"Unique visual IDs");for(Edge e:p.graph.edges)check(ids.contains(e.from)&&ids.contains(e.to),"No floating edge");for(Map.Entry<String,FlowCycle.Info> card:p.cards.entrySet()){check(p.graph.find(card.getKey()).kind==PROCESS,"Capsule visible");for(String id:card.getValue().members)check(card.getKey().equals(p.owner.get(id)),"Every hidden member represented");int exits=0;for(Edge e:p.graph.edges)if(e.from.equals(card.getKey())){exits++;check(e.branch.equals("next"),"Normalized view exit");}check(exits==1,"One visible exit");}for(Node n:original.nodes)check(ids.contains(n.id)||p.owner.containsKey(n.id),"Every node visible or represented");for(int i=0;i<p.graph.nodes.size();i++)for(int j=i+1;j<p.graph.nodes.size();j++){Node a=p.graph.nodes.get(i),b=p.graph.nodes.get(j);check(a.x+width(a)<=b.x||b.x+width(b)<=a.x||a.y+height(a)<=b.y||b.y+height(b)<=a.y,"Projected blocks do not overlap");}}
 static Document loop(int kind){Document d=FlowExamples.blank();return FlowLoopBuilder.prepare(d,null,d.edges.get(0).id,FlowLoopBuilder.Spec.defaults(kind)).project;}
 public static void main(String[] args){
  for(int kind=0;kind<3;kind++){Document d=loop(kind);FlowCycle.Info c=FlowCycle.find(d).get(0);for(Node n:d.nodes){n.comment="Nota di prova";if(n.kind==DECISION){n.trueLabel="Ripeti";n.falseLabel="Esci";n.trueColor="#123456";n.falseColor="#654321";}}d.find(c.check).breakpoint=true;d.find(c.check).breakpointCondition="i > 1";String before=FlowCodec.encode(d);FlowCycleView v=new FlowCycleView(d);check(v.cycles.size()==1&&v.cycles.get(0).kind==kind,"All loop kinds");FlowCycleView.Projection p=v.build();check(p.cards.size()==1&&p.graph.nodes.size()<d.nodes.size(),"Fold reduces real visual node count");check(p.graph.find(c.entry).breakpoint,"Hidden breakpoint remains indicated");verify(v,d,before);v.set(c.check,false);verify(v,d,before);check(v.build().graph.edges.size()==d.edges.size(),"Expansion restores every edge");for(Node n:v.build().graph.nodes)check("Nota di prova".equals(n.comment),"All notes retained");for(int k=0;k<8;k++){v.set(c.check,k%2==0);verify(v,d,before);}FlowCycleView.Projection broken=v.build();broken.graph.nodes.get(0).text="View only edit";broken.graph.edges.clear();verify(v,d,before);check(FlowCodec.encode(FlowCodec.decode(before)).equals(before),"Native save unchanged");}
  Document nested=FlowPseudocode.decode("PER i DA 1 A 2 FAI\nPER j DA 1 A 2 FAI\nSTAMPA i * 10 + j\nFINE PER\nFINE PER");String snap=FlowCodec.encode(nested);FlowCycleView nv=new FlowCycleView(nested);check(nv.cycles.size()==2,"Nested loops inventoried");FlowCycle.Info outer=Collections.max(nv.cycles,Comparator.comparingInt(c->c.members.size())),inner=Collections.min(nv.cycles,Comparator.comparingInt(c->c.members.size()));check(nv.build().cards.size()==1,"Only outer capsule initially");nv.set(outer.check,false);check(nv.build().cards.values().iterator().next().check.equals(inner.check),"Inner stays folded");verify(nv,nested,snap);nv.all(true);nv.set(inner.check,false);check(nv.folded.isEmpty(),"Opening nested cycle opens ancestors");verify(nv,nested,snap);nv.all(true);nv.set(inner.check,true);check(nv.build().cards.values().iterator().next().check.equals(inner.check),"Hidden inner selection reveals it");verify(nv,nested,snap);
  Document invalid=FlowCodec.decode(snap);Node start=invalid.nodes.stream().filter(n->n.kind==START).findFirst().get();invalid.edges.add(new Edge(start.id,outer.bodyEntry,"next"));FlowCycleView iv=new FlowCycleView(invalid);check(iv.cycles.stream().noneMatch(c->c.check.equals(outer.check)),"Multiple entry not folded");verify(iv,invalid,FlowCodec.encode(invalid));
  Document free=FlowExamples.blank();Node self=new Node(PROCESS,"x=1",800,0);free.nodes.add(self);free.edges.add(new Edge(self.id,self.id,"next"));FlowCycleView fv=new FlowCycleView(free);check(fv.cycles.isEmpty()&&fv.build().graph.edges.stream().anyMatch(e->e.from.equals(self.id)&&e.to.equals(self.id)),"Ordinary self loop preserved");verify(fv,free,FlowCodec.encode(free));check(new FlowCycleView(new Document()).build().graph.nodes.isEmpty(),"Empty graph safe");
  Document large=loop(1);FlowCycle.Info c=FlowCycle.find(large).get(0);Edge tail=large.edges.stream().filter(e->e.to.equals(c.check)&&c.members.contains(e.from)).findFirst().get();String previous=tail.from;large.edges.remove(tail);for(int i=large.nodes.size();i<500;i++){Node n=new Node(PROCESS,"i=i+0",0,0);large.nodes.add(n);large.edges.add(new Edge(previous,n.id,"next"));previous=n.id;}large.edges.add(new Edge(previous,c.check,"next"));long clock=System.nanoTime();FlowCycleView lv=new FlowCycleView(large);check(lv.cycles.size()==1&&lv.build().graph.nodes.size()<6,"500 block loop compacts");long ms=(System.nanoTime()-clock)/1000000;check(ms<15000,"Bounded inventory/layout time");System.out.println("LARGE_MS="+ms);verify(lv,large,FlowCodec.encode(large));
  System.out.println("CYCLE_VIEW_ANDROID PASS checks="+checks);
 }
}
